style.css:
/* Cambiar todo el color azul por negro */
* {
    color: white !important; /* Texto blanco */
    background-color: black !important; /* Fondo negro */
}

/* Aplicar efecto de glow al texto */
* {
    text-shadow: 0 0 5px #ffffff, 0 0 10px #ffffff, 0 0 15px #ffffff, 0 0 20px #ffffff, 0 0 25px #ffffff, 0 0 30px #ffffff, 0 0 35px #ffffff !important;
}

/* Asegurarse de que los enlaces no queden azules */
a {
    color: white !important;
    text-decoration: none !important;
    text-shadow: 0 0 5px #ffffff, 0 0 10px #ffffff, 0 0 15px #ffffff !important;
}

/* Opcionalmente, también puedes agregar sombras al fondo si lo deseas */
body {
    background-color: black !important;
}

/* Para que todos los elementos de la página sigan el estilo de glow */
* {
    outline: none !important;
}
